import { ref, onMounted, onBeforeUnmount } from 'vue';
import * as echarts from 'echarts';
import axios from 'axios';

// refs

export default {
  __name: 'TopologyGraph',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const chartRef = ref(null);
    let chartInstance = null;

    // 拿到拓扑数据
    const fetchTopology = async () => {
      try {
        const response = await axios.get('http://localhost:8081/topology/get');
        const {
          nodes,
          links
        } = response.data;
        renderGraph(nodes, links);
      } catch (error) {
        console.error('获取拓扑数据失败:', error);
      }
    };

    // 渲染图表
    const renderGraph = (nodes, links) => {
      if (!chartInstance && chartRef.value) {
        chartInstance = echarts.init(chartRef.value);
      }
      const option = {
        title: {
          text: 'Docker 容器拓扑图',
          left: 'center'
        },
        tooltip: {
          trigger: 'item',
          formatter: function (params) {
            if (params.dataType === 'node') {
              return `容器：${params.data.name}`;
            } else if (params.dataType === 'edge') {
              return `${params.data.source} ➔ ${params.data.target}`;
            }
          }
        },
        series: [{
          type: 'graph',
          layout: 'force',
          roam: true,
          label: {
            show: true,
            position: 'right',
            formatter: '{b}'
          },
          force: {
            repulsion: 200,
            edgeLength: 120
          },
          draggable: true,
          data: nodes.map(n => ({
            id: n.id,
            name: n.name,
            symbolSize: 60
          })),
          links: links.map(l => ({
            source: l.source,
            target: l.target
          }))
        }]
      };
      chartInstance.setOption(option);
    };

    // 自动加载拓扑
    onMounted(() => {
      fetchTopology();
    });

    // 销毁 ECharts 实例
    onBeforeUnmount(() => {
      if (chartInstance) {
        chartInstance.dispose();
      }
    });
    const __returned__ = {
      chartRef,
      get chartInstance() {
        return chartInstance;
      },
      set chartInstance(v) {
        chartInstance = v;
      },
      fetchTopology,
      renderGraph,
      ref,
      onMounted,
      onBeforeUnmount,
      get echarts() {
        return echarts;
      },
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
